window.docContents[13].resolve({"/Build-Tools-and-Distribution/Lake/#Lean-__________________--Build-Tools-and-Distribution--Lake--Configuration-File-Format--Lean-Format--Packages":{"contents":"Package ConfigurationThere can only be one package declaration per Lake configuration file.\nThe defined package configuration will be available for reference as _package.\n\nPost-Update HooksDeclare a post-lake update hook for the package.\nRuns the monadic action is after a successful lake update execution\nin this package or one of its downstream dependents.ExampleThis feature enables Mathlib to synchronize the Lean toolchain and run\ncache get after a lake update:lean_exe cache\npost_update pkg do\n  let wsToolchainFile := (← getRootPackage).dir / \"lean-toolchain\"\n  let mathlibToolchain ← IO.FS.readFile <| pkg.dir / \"lean-toolchain\"\n  IO.FS.writeFile wsToolchainFile mathlibToolchain\n  let exeFile ← runBuild cache.fetch\n  let exitCode ← env exeFile.toString #[\"get\"]\n  if exitCode ≠ 0 then\n    error s!\"{pkg.name}: failed to fetch cache\"\n\n\n","context":"Lean 中文参考手册\u0009Build Tools\u0009Lake\u0009Configuration File Format\u0009Lean Format","header":"24.1.3.2.2. Packages","id":"/Build-Tools-and-Distribution/Lake/#Lean-__________________--Build-Tools-and-Distribution--Lake--Configuration-File-Format--Lean-Format--Packages"}});